"use client"

import { useState, useEffect } from "react"
import { useDictionary } from "@/components/dictionary-provider"
import { createClient } from "@/lib/supabase"
import { 
  Table, 
  TableBody, 
  TableCell, 
  TableHead, 
  TableHeader, 
  TableRow 
} from "@/components/ui/table"
import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import { Plus, Package, Search } from "lucide-react"
import { Input } from "@/components/ui/input"

import { 
  Dialog, 
  DialogContent, 
  DialogHeader, 
  DialogTitle, 
  DialogTrigger,
  DialogFooter
} from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import { Save, X } from "lucide-react"

import { SectionLoader } from "@/components/section-loader"

export default function ProductsPage() {
  const { dict } = useDictionary()
  const supabase = createClient()
  const [products, setProducts] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [isOpen, setIsOpen] = useState(false)
  const [editingProduct, setEditingProduct] = useState<any>(null)

  const [formData, setFormData] = useState({
    sku: "",
    name: "",
    base_price: 0
  })

  async function fetchProducts() {
    setLoading(true)
    const { data, error } = await supabase.from("products").select("*").order('created_at', { ascending: false })
    if (!error && data) setProducts(data)
    setLoading(false)
  }

  useEffect(() => {
    fetchProducts()
  }, [])

  const handleOpenDialog = (product: any = null) => {
    if (product) {
      setEditingProduct(product)
      setFormData({ 
        sku: product.sku, 
        name: product.name, 
        base_price: product.base_price 
      })
    } else {
      setEditingProduct(null)
      setFormData({ sku: "", name: "", base_price: 0 })
    }
    setIsOpen(true)
  }

  const handleSubmit = async (e: React.SyntheticEvent<HTMLFormElement, SubmitEvent>) => {
    e.preventDefault()
    const payload = { ...formData }
    
    if (editingProduct) {
      const { error } = await supabase.from("products").update(payload).eq("id", editingProduct.id)
      if (!error) setIsOpen(false)
    } else {
      const { error } = await supabase.from("products").insert([payload])
      if (!error) setIsOpen(false)
    }
    fetchProducts()
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <h1 className="page-title">{dict.TITLE_PRODUCTS}</h1>
        
        <Dialog open={isOpen} onOpenChange={setIsOpen}>
          <DialogTrigger asChild>
            <Button className="interactive-click interactive-focus" onClick={() => handleOpenDialog()}>
              <Plus data-icon="inline-start" />
              {dict.TITLE_ADD_PRODUCT}
            </Button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-[425px]">
            <DialogHeader>
              <DialogTitle>
                {editingProduct ? dict.TITLE_EDIT_PRODUCT : dict.TITLE_ADD_PRODUCT}
              </DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="flex flex-col gap-4 py-4">
              <div className="flex flex-col gap-2">
                <Label htmlFor="sku">{dict.LABEL_SKU}</Label>
                <Input 
                  id="sku" 
                  value={formData.sku} 
                  onChange={(e) => setFormData({ ...formData, sku: e.target.value })}
                  placeholder="OIL-001"
                  className="interactive-focus"
                  required
                />
              </div>
              <div className="flex flex-col gap-2">
                <Label htmlFor="name">{dict.LABEL_PRODUCT_NAME}</Label>
                <Input 
                  id="name" 
                  value={formData.name} 
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="Diesel Premium"
                  className="interactive-focus"
                  required
                />
              </div>
              <div className="flex flex-col gap-2">
                <Label htmlFor="base_price">{dict.LABEL_BASE_PRICE}</Label>
                <Input 
                  id="base_price" 
                  type="number"
                  step="0.01"
                  value={formData.base_price} 
                  onChange={(e) => setFormData({ ...formData, base_price: parseFloat(e.target.value) })}
                  className="interactive-focus"
                  required
                />
              </div>
              <DialogFooter className="mt-4">
                <Button type="button" variant="outline" onClick={() => setIsOpen(false)} className="interactive-click">
                  <X data-icon="inline-start" />
                  {dict.BUTTON_CANCEL}
                </Button>
                <Button type="submit" className="interactive-click">
                  <Save data-icon="inline-start" />
                  {dict.BUTTON_SAVE}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <div className="action-bar">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-2.5 top-2.5 size-4 text-muted-foreground" />
          <Input 
            placeholder={dict.SEARCH_PLACEHOLDER} 
            className="pl-8 interactive-focus"
          />
        </div>
      </div>

      <Card className="data-card">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead><Package className="size-4 mr-2 inline-block" />{dict.LABEL_NAME}</TableHead>
              <TableHead>{dict.LABEL_SKU}</TableHead>
              <TableHead className="text-right">{dict.LABEL_BASE_PRICE}</TableHead>
              <TableHead className="text-right">{dict.LABEL_ACTIONS}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow><TableCell colSpan={4} className="text-center py-8">{dict.LOADING}</TableCell></TableRow>
            ) : products.length === 0 ? (
              <TableRow><TableCell colSpan={4} className="text-center py-8">{dict.NO_DATA}</TableCell></TableRow>
            ) : (
              products.map((product) => (
                <TableRow key={product.id} className="interactive-focus">
                  <TableCell className="font-medium">{product.name}</TableCell>
                  <TableCell>{product.sku}</TableCell>
                  <TableCell className="text-right font-mono">${product.base_price?.toFixed(2)}</TableCell>
                  <TableCell className="text-right">
                    <Button 
                      variant="ghost" 
                      size="sm" 
                      className="interactive-click"
                      onClick={() => handleOpenDialog(product)}
                    >
                      {dict.BUTTON_EDIT}
                    </Button>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </Card>
    </div>
  )
}